import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import * as projen from 'projen'
import { GitHubTemplates } from 'projen-github-templates'

const outdir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke-'))
const project = new projen.Project({ name: 'smoke', outdir })
const read = (file) => fs.readFileSync(path.join(outdir, file), 'utf8')

new GitHubTemplates(project, {
  files: {
    '.github/ISSUE_TEMPLATE/bug.yml': {
      name: 'Bug report',
      description: 'Report a bug',
      body: [
        {
          type: 'input',
          attributes: { label: 'Version' },
          validations: { required: true },
        },
      ],
    },
    '.github/ISSUE_TEMPLATE/config.yml': { blankIssuesEnabled: false },
    '.github/ISSUE_TEMPLATE/feature.md': {
      name: 'Feature request',
      about: 'Request a feature',
      body: ['Describe it'],
    },
    '.github/pull_request_template.md': { body: ['Describe the change'] },
  },
})

project.synth()

assert.ok(read('.github/ISSUE_TEMPLATE/bug.yml').includes('required: true'))
assert.ok(
  read('.github/ISSUE_TEMPLATE/config.yml').includes(
    'blank_issues_enabled: false',
  ),
)
assert.ok(read('.github/ISSUE_TEMPLATE/feature.md').includes('Describe it'))
assert.ok(
  read('.github/pull_request_template.md').includes('Describe the change'),
)
